CREATE OR REPLACE PROCEDURE sp(para_Team_ID NUMBER, para_School_ID NUMBER, para_Founded NUMBER) IS
  CURSOR all_rows IS SELECT * FROM "basketball_match";
  all_rec "basketball_match"%ROWTYPE;
  CURSOR ref_cursor IS SELECT * FROM "basketball_match" FOR UPDATE;
  rec "basketball_match"%ROWTYPE;
  v_count NUMBER;
BEGIN
  OPEN all_rows;
  LOOP
    FETCH all_rows INTO all_rec;
    EXIT WHEN all_rows%NOTFOUND;

    IF all_rec."School_ID" <= para_School_ID THEN
      UPDATE "basketball_match"
         SET "School_ID" = para_School_ID + 100
       WHERE "Team_ID" = all_rec."Team_ID";
    END IF;
  END LOOP;
  CLOSE all_rows;

  OPEN ref_cursor;
  LOOP
    FETCH ref_cursor INTO rec;
    EXIT WHEN ref_cursor%NOTFOUND;

    SELECT COUNT(*)
      INTO v_count
      FROM "basketball_match"
     WHERE "Team_ID" = rec."Team_ID"
       AND "Team_ID" > para_Team_ID;

    IF v_count > 0 THEN
      UPDATE "basketball_match"
         SET "School_ID" = para_School_ID - 10
       WHERE CURRENT OF ref_cursor;
    ELSE
      UPDATE "basketball_match"
         SET "School_ID" = para_School_ID - 20
       WHERE CURRENT OF ref_cursor;
    END IF;
  END LOOP;
  CLOSE ref_cursor;

  UPDATE "university"
     SET "Founded" = para_Founded;
END;

