DECLARE
  v_old_bm VARCHAR2(4000); v_new_bm VARCHAR2(4000);
  v_old_uni VARCHAR2(4000); v_new_uni VARCHAR2(4000);
  PROCEDURE test_one(pt NUMBER, ps NUMBER, pf NUMBER) IS
  BEGIN
    SAVEPOINT s;
    sp_old(pt, ps, pf);
    SELECT LISTAGG("Team_ID"||':'||NVL(TO_CHAR("School_ID"),'NULL'), ',') WITHIN GROUP (ORDER BY "Team_ID") INTO v_old_bm FROM "basketball_match";
    SELECT LISTAGG("School_ID"||':'||NVL(TO_CHAR("Founded"),'NULL'), ',') WITHIN GROUP (ORDER BY "School_ID") INTO v_old_uni FROM "university";
    ROLLBACK TO s;
    sp_new(pt, ps, pf);
    SELECT LISTAGG("Team_ID"||':'||NVL(TO_CHAR("School_ID"),'NULL'), ',') WITHIN GROUP (ORDER BY "Team_ID") INTO v_new_bm FROM "basketball_match";
    SELECT LISTAGG("School_ID"||':'||NVL(TO_CHAR("Founded"),'NULL'), ',') WITHIN GROUP (ORDER BY "School_ID") INTO v_new_uni FROM "university";
    IF v_old_bm = v_new_bm AND v_old_uni = v_new_uni THEN
      DBMS_OUTPUT.PUT_LINE('OK p='||pt||','||ps||','||pf);
    ELSE
      DBMS_OUTPUT.PUT_LINE('DIFF p='||pt||','||ps||','||pf||' old='||v_old_bm||' new='||v_new_bm||' oldu='||v_old_uni||' newu='||v_new_uni);
    END IF;
    ROLLBACK TO s;
  END;
BEGIN
  test_one(2,5,1900);
  test_one(-10,3,-1);
  test_one(4,0,0);
  test_one(NULL,5,1900);
  test_one(2,NULL,1900);
  test_one(NULL,NULL,NULL);
  test_one(2,5,NULL);
END;

